// The reTerminal Sticky's own layout: a thin bar along the top of every scene
// (the time, the date, the signal, the battery), and around the scene list a
// home screen with the same, big, and how to get around: what each key does
// and the swipes, read off the frame's event map. One header that shrinks:
// big over the list, a line over a scene, none over a scene that asks for the
// whole glass (a reader's "Full screen"). Swipe up from the bottom for the
// scene list, down from the top for the settings, in from a side for the
// scene's back and forward. The settings (the scene's, the frame's, the
// layout's) hang from the bar: it stays over them with no rule under it, as
// if they were pulled down out of it. The other look: nothing, the scene on
// the whole glass. What it shows, and what the Action key does for the
// layout, are its settings.
// Black on white, or white on black (the "Colors" setting, put in place at
// the start of each render).
let INK = '#000000'
let GREY = '#555555'
let PAPER = '#ffffff'

const pad = (n) => String(n).padStart(2, '0')

// The layout's settings as it uses them. A switch comes as true / false or as
// its text, and is on until it is turned off.
const on = (value) => value !== false && value !== 'false'
const SIZES = { small: 0.85, normal: 1, large: 1.2 }
function settingsOf(state) {
  return {
    home: on(state.home),
    refresh: on(state.refresh),
    date: on(state.date),
    swipes: on(state.swipes),
    signal: on(state.signal),
    battery: on(state.battery),
    clock: state.clock === '12' || state.clock === 'off' ? state.clock : '24',
    dark: state.colors === 'dark',
    scale: SIZES[state.size] || 1,
  }
}
const DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October',
  'November', 'December']

// What the frame's own event map says on a Sticky, for a frame that has none
// to tell (the preview): BOARD_KEYS.seeed_reterminal_sticky.eventMap, copied
// from frontend/src/generated/boardKeys.gen.ts
// (frameos/tools/generate_board_keys.py, docs/buttons.md), since a scene
// imports nothing of the repository's. The Action key held talks, the arrows
// held walk the scenes (by role, so they turn with the frame), two keys
// together are Back and held the scene list, and the edge swipes.
const STICKY_MAP = [
  { event: 'button', match: { label: 'AI', action: 'longPress' }, emit: 'voiceChat', as: {} },
  { event: 'button', match: { role: 'prev', action: 'longPress' }, emit: 'setCurrentScene', as: { direction: 'prev' } },
  { event: 'button', match: { role: 'next', action: 'longPress' }, emit: 'setCurrentScene', as: { direction: 'next' } },
  { event: 'button', match: { role: 'back', action: 'press' }, emit: 'back', as: {} },
  { event: 'button', match: { role: 'back', action: 'longPress' }, emit: 'sceneSwitcher', as: {} },
  { event: 'edgeSwipe', match: { edge: 'right' }, emit: 'forward', as: {} },
  { event: 'edgeSwipe', match: { edge: 'left' }, emit: 'back', as: {} },
  { event: 'edgeSwipe', match: { edge: 'bottom' }, emit: 'sceneSwitcher', as: {} },
  { event: 'edgeSwipe', match: { edge: 'top' }, emit: 'sceneSettings', as: {} },
]
// The Action key, the one a hand finds (Seeed prints AI on it, and AI stays
// its label in the event map): pressed, go; held, talk. The layout listens to
// it too: a press, where the map leaves the press to the scene, draws the
// picture again.
const ACTION_KEY = 'AI'
// How long a key is held before it is a hold (buttons.longPressMs).
const HOLD_MS = 1000

// A key's role as the frame hears it (docs/buttons.md): AI is the Action key,
// `primary`, and an arrow is `next` where it points to the right or the bottom
// of the picture as the frame hangs, else `prev` (input_state.nim `facing`; a
// flip, which a layout is not told, aside). Where an arrow points is where it
// sits on the panel unturned (the preset's EMBEDDED_BOARD_KEYS): UP and DOWN
// are up and down in the portrait a Sticky is held in, 270 degrees from its
// 800x480 panel, so unturned UP is to the left of DOWN. At 270 UP is prev and
// DOWN next; held the other way up (90) the other way round.
const POINTS = { UP: [-1, 0], DOWN: [1, 0] }
function roleOf(label, rotate) {
  const p = POINTS[label]
  if (!p) return 'primary'
  const [x, y] = { 90: [p[1], -p[0]], 180: [-p[0], -p[1]], 270: [-p[1], p[0]] }[rotate] || p
  return (Math.abs(x) >= Math.abs(y) ? x > 0 : y > 0) ? 'next' : 'prev'
}
const turnOf = (frame) => ((Number(frame.rotate) || 0) % 360 + 360) % 360

// What the frame's event map makes of a key, in a word. Under an arrow that
// already says which way, a scene change is just "Scene".
function said(rule) {
  switch (rule.emit) {
    case 'setCurrentScene': return 'Scene'
    case 'voiceChat': return 'Talk'
    case 'sceneSwitcher': return 'Scenes'
    case 'sceneSettings': return 'Settings'
    case 'toggleScreen': return 'Screen'
    case 'render': return 'Refresh'
    case 'back': return 'Back'
    case 'forward': return 'Forward'
    default: return rule.emit ? String(rule.emit) : null
  }
}
// The rule of the frame's map that takes a press (`action`: press, longPress),
// the first whose every match value the press carries, as the dispatcher reads
// them (event_map.nim): a rule names a key by its label or by its role.
function ruleFor(map, press) {
  return map.find((rule) => rule.event === 'button' && rule.match &&
    Object.keys(rule.match).every((key) => String(rule.match[key]) === String(press[key])))
}
const keyRule = (map, label, action, rotate) => ruleFor(map, { label, role: roleOf(label, rotate), action })
// Two keys pressed together: the Back key of a board that has none, where the
// map binds a `back` by role (docs/buttons.md).
const bothRule = (map, action) => ruleFor(map, { role: 'back', action })
const swipeRule = (map, edge) => map.find((rule) => rule.event === 'edgeSwipe' && rule.match && rule.match.edge === edge)
const eventMap = (frame) => (Array.isArray(frame.eventMap) ? frame.eventMap : STICKY_MAP)

// The scene list is showing (built in, its id `system/sceneSwitcher`).
const listShows = (frame) => frame.systemScene === true && String(frame.sceneId || '').startsWith('system/sceneSwitcher')
// The settings are showing (built in, `system/sceneSettings`): the scene's,
// the frame's or the layout's page.
const settingsShow = (frame) =>
  frame.systemScene === true && String(frame.sceneId || '').startsWith('system/sceneSettings')

// The Action key's press draws the picture again, where the frame's map
// leaves the press to the scene and the owner has not turned it off. The
// layout hears the key's edges (`gpio`), never its `button`: a layout that
// listens for `button` makes every scene it wraps one that does, and such a
// scene's arrows are no longer its forward and back (docs/buttons.md). A press
// is the key let go before it is a hold, with no other key moving meanwhile
// (two keys are Back).
let pressing = false
let alone = true
export function onEvent(app, context) {
  const edge = context.payload || {}
  if (context.event !== 'gpio') return false
  if (edge.label !== ACTION_KEY) {
    if (pressing) alone = false
    return false
  }
  if (edge.action === 'down') {
    pressing = alone = true
    return false
  }
  const press = edge.action === 'up' && alone && !edge.claimed && !(Number(edge.durationMs) >= HOLD_MS)
  pressing = false
  alone = true
  if (!press || app.frame.systemScene || !settingsOf(app.state).refresh) return false
  const map = eventMap(app.frame)
  const taken = ['press', 'doublePress', 'triplePress'].some((action) => keyRule(map, ACTION_KEY, action, turnOf(app.frame)))
  if (!taken) frameos.dispatch('render')
  return false
}

// The Wi-Fi signal as a fan of four, the dot and three arcs: the strength
// solid, the rest a hairline down the middle of its arc. One ink, crisp on
// e-paper. Nothing on a frame that cannot tell (the preview, a Pi, a frame
// off its network).
const WIFI_FAN = [
  { band: 'M12 20L9.525 17.525A3.5 3.5 0 0 1 14.475 17.525Z' },
  {
    band: 'M6.697 14.697A7.5 7.5 0 0 1 17.303 14.697L15.536 16.464A5 5 0 0 0 8.464 16.464Z',
    line: 'M7.581 15.581A6.25 6.25 0 0 1 16.419 15.581',
  },
  {
    band: 'M3.868 11.868A11.5 11.5 0 0 1 20.132 11.868L18.364 13.636A9 9 0 0 0 5.636 13.636Z',
    line: 'M4.752 12.752A10.25 10.25 0 0 1 19.248 12.752',
  },
  {
    band: 'M1.04 9.04A15.5 15.5 0 0 1 22.96 9.04L21.192 10.808A13 13 0 0 0 2.808 10.808Z',
    line: 'M1.924 9.924A14.25 14.25 0 0 1 22.076 9.924',
  },
]
function Signal({ rssi, u, color }) {
  if (typeof rssi !== 'number') return null
  const level = rssi >= -55 ? 4 : rssi >= -65 ? 3 : rssi >= -75 ? 2 : 1
  const w = Math.round(u * 4.6)
  return (
    <svg viewBox="0 8 24 13" width={w} height={Math.round((w * 13) / 24)}>
      {WIFI_FAN.map((arc, i) =>
        i < level ? <path d={arc.band} fill={color} /> : <path d={arc.line} fill="none" stroke={color} strokeWidth={1} />,
      )}
    </svg>
  )
}

function Battery({ percent, u, color }) {
  if (typeof percent !== 'number') return null
  const w = Math.round(u * 5)
  const h = Math.round(u * 2.6)
  const line = Math.max(1, Math.round(u * 0.3))
  const inner = Math.max(0, Math.round((w - 4 * line) * Math.min(100, Math.max(0, percent)) / 100))
  return (
    <div className="flex items-center gap-[3px]">
      <div className={`flex items-center w-[${w}px] h-[${h}px] p-[${line}px] border-[${line}px] border-[${color}] rounded-[${line * 2}px]`}>
        <div className={`h-full w-[${inner}px] bg-[${color}]`} />
      </div>
      <div className={`w-[${line * 2}px] h-[${Math.round(h / 2.5)}px] bg-[${color}]`} />
      <span className={`pl-[${line * 2}px] text-[${Math.round(u * 3)}px] font-semibold`}>{`${percent}%`}</span>
    </div>
  )
}

// The time, as the "Time" setting says; null for none.
function clock(now, format) {
  if (format === 'off') return null
  if (format === '12') return `${now.getHours() % 12 || 12}:${pad(now.getMinutes())}${now.getHours() < 12 ? 'am' : 'pm'}`
  return `${pad(now.getHours())}:${pad(now.getMinutes())}`
}

// What a key does, in a word: go, back, home.
function actionSaid(rule, set) {
  if (rule.emit === 'sceneSwitcher') return set.home ? 'home' : 'scenes'
  return said(rule).toLowerCase()
}

// How to get around, read off the frame's event map, a line each: the Action key,
// the arrows, two keys together, the swipes. The home screen is where this is
// told: nothing on a scene says it (a rail of tabs beside the keys did, and
// was never used).
function helpLines(map, set, rotate) {
  const lines = []
  // The Action key: pressed, the scene's (what is picked opens, and the
  // layout draws the picture again), unless the map binds it; held, the map's.
  const action = []
  const pressed = keyRule(map, ACTION_KEY, 'press', rotate)
  action.push(`press: ${pressed ? actionSaid(pressed, set) : 'go'}`)
  const held = keyRule(map, ACTION_KEY, 'longPress', rotate)
  if (held) action.push(`hold: ${actionSaid(held, set)}`)
  lines.push({ key: 'Action', text: action.join(' · ') })
  // The arrows: here they move through the list; held, the map's (a scene
  // back or on, from anywhere, which way as the frame hangs).
  const arrows = ['here: move']
  const upHeld = keyRule(map, 'UP', 'longPress', rotate)
  const downHeld = keyRule(map, 'DOWN', 'longPress', rotate)
  const way = (rule) => (rule.as && rule.as.direction === 'next' ? 'next' : 'previous')
  if (upHeld && downHeld && upHeld.emit === 'setCurrentScene' && downHeld.emit === 'setCurrentScene') {
    arrows.push(`hold: ${way(upHeld)} / ${way(downHeld)} scene`)
  } else {
    if (upHeld) arrows.push(`hold up: ${said(upHeld).toLowerCase()}`)
    if (downHeld) arrows.push(`hold down: ${said(downHeld).toLowerCase()}`)
  }
  lines.push({ key: 'Up/Down', text: arrows.join(' · ') })
  // Two keys together, where the map makes them the Back key.
  const both = []
  const bothPressed = bothRule(map, 'press')
  if (bothPressed) both.push(`press: ${actionSaid(bothPressed, set)}`)
  const bothHeld = bothRule(map, 'longPress')
  if (bothHeld) both.push(`hold: ${actionSaid(bothHeld, set)}`)
  if (both.length) lines.push({ key: 'Two keys', text: both.join(' · ') })
  const swipes = []
  if (swipeRule(map, 'bottom')) swipes.push('up: this list')
  if (swipeRule(map, 'top')) swipes.push('down: settings')
  if (swipeRule(map, 'left') || swipeRule(map, 'right')) swipes.push('sideways: back / forward')
  if (swipes.length) lines.push({ key: 'Swipe', text: swipes.join(' · ') })
  return lines
}

// The scene list, as a home screen: the time and the date over it, the
// battery and the signal, and under it how to get around.
function Home({ app, u, set, now }) {
  const map = eventMap(app.frame)
  const time = clock(now, set.clock)
  // How to get around, unless the owner turned that help off; none while the
  // search has the keyboard up, which takes its room.
  const help = set.swipes && !app.frame.typing ? helpLines(map, set, turnOf(app.frame)) : []

  const main = (
    <div className={`flex flex-col w-full h-full min-w-0 min-h-0 bg-[${PAPER}] text-[${INK}]`}>
      <div className={`flex items-end px-[${Math.round(u * 4)}px] pt-[${Math.round(u * 3)}px] pb-[${Math.round(u * 1.5)}px] gap-[${Math.round(u * 2)}px]`}>
        <div className="flex flex-col flex-1 min-w-0">
          {time ? <span className={`text-[${Math.round(u * 13)}px] font-bold leading-none`}>{time}</span> : null}
          {set.date ? (
            <span className={`text-[${Math.round(u * (time ? 3.6 : 6))}px] ${time ? `text-[${GREY}]` : ''} font-semibold truncate pt-[${Math.round(u)}px]`}>
              {`${DAYS[now.getDay()]}, ${now.getDate()} ${MONTHS[now.getMonth()]}`}
            </span>
          ) : null}
          {!time && !set.date ? <span className={`text-[${Math.round(u * 6)}px] font-bold leading-none`}>Scenes</span> : null}
        </div>
        <div className={`flex flex-col items-end gap-[${Math.round(u * 1.5)}px] pb-[${Math.round(u * 0.5)}px]`}>
          {set.battery ? <Battery percent={app.frame.batteryPercent} u={u} color={INK} /> : null}
          {set.signal ? <Signal rssi={app.frame.wifiRssi} u={u} color={INK} /> : null}
        </div>
      </div>
      <div className={`flex flex-col flex-1 min-h-0 border-t-2 border-[${INK}]`}>
        <yield />
      </div>
      {help.length ? (
        <div className={`flex flex-col gap-[${Math.round(u * 0.8)}px] px-[${Math.round(u * 4)}px] py-[${Math.round(u * 2)}px] border-t-2 border-[${INK}] text-[${Math.round(u * 2.9)}px]`}>
          {help.map((line) => (
            <div className={`flex items-baseline gap-[${Math.round(u * 1.5)}px] min-w-0`}>
              <span className={`shrink-0 w-[${Math.round(u * 16)}px] font-bold whitespace-nowrap`}>{line.key}</span>
              <span className={`flex-1 min-w-0 text-[${GREY}] font-semibold`}>{line.text}</span>
            </div>
          ))}
        </div>
      ) : null}
    </div>
  )
  return main
}

// The bar along the top of a scene: the home screen's header made small, the
// time and the date (a tap: the scene list) on the left, the signal and the
// battery (a tap: the frame's page) on the right. One ink, a rule under it,
// none over the settings (`ruled` false), which hang from it.
function Bar({ app, u, set, now, ruled = true }) {
  const time = clock(now, set.clock)
  const date = set.date ? `${DAYS[now.getDay()].slice(0, 3)} ${now.getDate()} ${MONTHS[now.getMonth()].slice(0, 3)}` : null
  return (
    <div className={`flex flex-col w-full h-full bg-[${PAPER}] text-[${INK}]`}>
      <div className={`flex items-center h-[${Math.round(u * 6.5)}px] px-[${Math.round(u * 3)}px] gap-[${Math.round(u * 2)}px] ${ruled ? `border-b-2 border-[${INK}]` : ''} text-[${Math.round(u * 3.4)}px]`}>
        <div className={`flex flex-1 items-center min-w-0 h-full gap-[${Math.round(u * 1.6)}px]`} onClick={() => frameos.dispatch('sceneSwitcher')}>
          {time ? <span className="font-bold whitespace-nowrap">{time}</span> : null}
          {date ? <span className="font-semibold truncate">{date}</span> : null}
        </div>
        <div className={`flex items-center h-full gap-[${Math.round(u * 2.2)}px]`} onClick={() => frameos.dispatch('sceneSettings', { page: 'frame' })}>
          {set.signal ? <Signal rssi={app.frame.wifiRssi} u={u} color={INK} /> : null}
          {set.battery ? <Battery percent={app.frame.batteryPercent} u={u} color={INK} /> : null}
        </div>
      </div>
      <div className="flex flex-col flex-1 min-h-0">
        <yield />
      </div>
    </div>
  )
}

export function get(app) {
  const frame = app.frame
  const W = frame.width
  const H = frame.height
  const set = settingsOf(app.state)
  INK = set.dark ? '#ffffff' : '#000000'
  PAPER = set.dark ? '#000000' : '#ffffff'
  GREY = set.dark ? '#aaaaaa' : '#555555'
  // One unit, a hundredth of the shorter edge (the same look either way
  // round), times the "Text size".
  const u = Math.min(W, H) / 100 * set.scale
  const now = new Date()
  // A clock to the minute: the header is due again when the minute turns. On
  // e-paper that never wakes the panel (the scene's own interval stays the
  // fastest it draws, scene_rhythm.nim): the time shown is when the picture
  // was drawn, brought up to date on the scene's next render.
  const clocked = () => {
    if (set.clock !== 'off' || set.date) frameos.setNextSleep(60 - now.getSeconds())
  }
  if (listShows(frame) && set.home) {
    clocked()
    return <Home app={app} u={u} set={set} now={now} />
  }
  // "Nothing" is the whole glass, and so is a look this layout no longer has
  // (the rail beside the keys, before 2026.11.15).
  const barred = (app.state.look || 'bar') === 'bar'
  // The settings, pulled down from the top: they hang from the bar, no rule
  // between the two. Their keyboard up, they get the whole glass.
  if (settingsShow(frame) && barred && !frame.typing) {
    clocked()
    return <Bar app={app} u={u} set={set} now={now} ruled={false} />
  }
  // The scene list with no home screen gets the whole glass, and so does a
  // scene while its keyboard is up, and one that asks for it (a reader, its
  // "Full screen" setting: app.frame.fullScreen).
  if (frame.systemScene || frame.typing || frame.fullScreen) return <yield />
  if (!barred) return <yield />
  clocked()
  return <Bar app={app} u={u} set={set} now={now} />
}
